import java.util.Scanner;

public class Main {
    static final long MODULUS = 1000000007;

    static class MatStruct {
        long[][] mat;
        int dim;

        MatStruct(int size) {
            this.dim = size;
            this.mat = new long[size][size];
        }

        static MatStruct multiply(MatStruct A, MatStruct B) {
            MatStruct C = new MatStruct(A.dim);
            for (int i = 0; i < A.dim; ++i) {
                for (int j = 0; j < A.dim; ++j) {
                    C.mat[i][j] = 0;
                    for (int k = 0; k < A.dim; ++k) {
                        C.mat[i][j] += A.mat[i][k] * B.mat[k][j];
                    }
                    C.mat[i][j] %= MODULUS;
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n_value = sc.nextLong();
        long m_value = sc.nextLong();

        int size = (int) (m_value + 1);
        MatStruct base = new MatStruct(size);
        MatStruct identity = new MatStruct(size);

        for (int i = 0; i <= m_value; ++i) {
            base.mat[i][i] = 1;
            base.mat[0][i] = 1;
        }
        for (int i = 0; i <= m_value; ++i) {
            identity.mat[i][i] = 1;
        }

        long y_counter = 1;
        long y_powered = 1;
        int level_idx = 0;
        long total_sum = 0;

        while (y_powered * m_value <= n_value) {
            y_powered *= m_value;
            level_idx++;
        }

        // Initialize bi_array
        MatStruct[][] bi_array = new MatStruct[level_idx + 1][m_value + 1];
        for (int t = 0; t <= level_idx; ++t) {
            for (int i = 0; i <= m_value; ++i) {
                bi_array[t][i] = new MatStruct(size);
            }
        }

        for (int t = 0; t <= level_idx; ++t) {
            if (t > 0) {
                bi_array[t][0] = copyMat(bi_array[t - 1][0]);
                for (int i = 1; i <= m_value; ++i) {
                    bi_array[t][0] = MatStruct.multiply(bi_array[t][0], bi_array[t - 1][i]);
                }
            }
            for (int i = 1; i <= m_value; ++i) {
                bi_array[t][i] = copyMat(bi_array[t][i - 1]);
                // Swap rows
                for (int j = m_value - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_value; ++k) {
                        long temp = bi_array[t][i].mat[j][k];
                        bi_array[t][i].mat[j][k] = bi_array[t][i].mat[j + 1][k];
                        bi_array[t][i].mat[j + 1][k] = temp;
                    }
                }
                // Swap columns
                for (int j = m_value - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_value; ++k) {
                        long temp = bi_array[t][i].mat[k][j];
                        bi_array[t][i].mat[k][j] = bi_array[t][i].mat[k][j + 1];
                        bi_array[t][i].mat[k][j + 1] = temp;
                    }
                }
            }
        }

        MatStruct currentMat = copyMat(identity);
        while (total_sum < n_value) {
            if (total_sum + y_powered <= n_value) {
                total_sum += y_powered;
                currentMat = MatStruct.multiply(currentMat, bi_array[level_idx][0]);
                y_counter = (y_counter + 1) % m_value;
            } else {
                y_powered /= m_value;
                level_idx--;
            }
        }

        long final_answer = 0;
        for (int i = 0; i <= m_value; ++i) {
            final_answer = (final_answer + currentMat.mat[i][m_value]) % MODULUS;
        }
        System.out.println(final_answer);
        sc.close();
    }

    static MatStruct copyMat(MatStruct original) {
        MatStruct copy = new MatStruct(original.dim);
        for (int i = 0; i < original.dim; ++i) {
            System.arraycopy(original.mat[i], 0, copy.mat[i], 0, original.dim);
        }
        return copy;
    }
